{
  "reviews": [
    {
      "benchmark": "arc",
      "instrument_review": {
        "instrument": {
          "name": "EFPA Test Review Model",
          "version": "5.0, August 2025",
          "attribution": "European Federation of Psychologists’ Associations AISBL, 2025; https://www.efpa.eu/; CC BY-SA 4.0.",
          "source": "User-supplied extraction of Papers/EFPA_test_review_model_2025.pdf.",
          "source_sha256": "c6a63e9f87cefe9b3ac829b41593c415f3f486d59249594cde538820ab32ce0b",
          "scope": "ARC-AGI-2 public test problems, official scoring software and ARC Prize verified-testing rules, as described in the supplied passage.",
          "rating_key": {
            "n/a": "Not applicable",
            "0": "Insufficient information to rate",
            "1": "Inadequate",
            "2": "Adequate",
            "3": "Good",
            "4": "Excellent"
          },
          "rating_policy": "Original EFPA scale retained. Section judgments are reasoned, not averaged. Zero denotes insufficient evidence, not demonstrated poor quality. No aggregate benchmark-quality score is calculated."
        },
        "part_A": {
          "1": {
            "reviewer": "Unassigned",
            "date_of_current_review": "Not supplied",
            "date_of_previous_review": "Not supplied",
            "instrument_name_local": "ARC-AGI-2",
            "short_name": "ARC-AGI-2",
            "original_name_if_adaptation": "n/a; no local adaptation identified",
            "original_authors": "ARC Prize Foundation staff and partners; François Chollet and colleagues credited for the technical-report figure. Complete authorship not supplied.",
            "local_adaptation_authors": "n/a; no local adaptation identified",
            "local_distributor_publisher": "ARC Prize Foundation is identified as developer and verified-evaluation organization; separate distributor information is not supplied.",
            "original_publisher_if_different": "Not supplied",
            "current_revision_publication_date": "Not supplied; source inspection occurred on 7 October 2026.",
            "local_adaptation_publication_date": "n/a",
            "original_publication_date": "Not supplied"
          },
          "2": {
            "2.1": "Other: rule induction, grid problem solving, abstract reasoning.",
            "2.2": "Other: AI evaluation and research.",
            "2.3": "AI systems evaluated on unfamiliar grid problems; specific inclusion boundaries are not supplied.",
            "2.4": "Not explicitly stated; researchers can inspect public materials.",
            "2.5": "One overall task-performance score is described; no separately established skill scales.",
            "2.6": "Other: digitally returned output grids. Exact response interface is not supplied.",
            "2.7": {
              "attention": "Human attention prerequisite n/a; AI handling of examples and inputs is relevant but not separately specified.",
              "command_of_test_language": "Information missing on language demands of instructions and interfaces.",
              "language_fluency": "Information missing; no separate fluency requirement established.",
              "digital_skills_experience": "Reinterpreted as interface compatibility; information missing on exact requirements.",
              "handedness": "Irrelevant / not necessary for AI.",
              "hearing": "Irrelevant / not necessary for the described grid tasks.",
              "motor_capabilities": "Human motor capabilities n/a; digital output production is required.",
              "reading": "Human reading n/a; parsing instructions and grid encodings is relevant, with requirements incompletely specified.",
              "vision": "Human vision n/a; processing grid structure is required, but permitted encodings and modalities are not fully supplied.",
              "writing": "Human writing n/a; output-grid generation is required and exact matching is specified.",
              "other": "Inferring transformations and producing correctly sized, correctly coloured grids are required."
            },
            "2.8": "Verified evaluations specify AI settings and a spending limit and use one run. Numerical limits and complete execution procedures are not supplied. Other routes may differ.",
            "2.9": "Production-based open grid outputs; two attempts per new input. Exact-match correctness is scored. Times are reportedly released, but latency is not described as a score component.",
            "2.10": "Coloured two-dimensional grids; instructions and grid presentation are mentioned. Exact machine stimulus encoding is not supplied.",
            "2.11": "1,000 development problems; public, semi-private and private test sets each contain 120 problems. Number of new input grids per problem varies; minimum, maximum and typical counts are not supplied.",
            "2.12.1": "Individual administration, reinterpreted as evaluating one AI configuration.",
            "2.12.2": "Verified testing is controlled, recorded and run or verified by ARC Prize. Human proctor and testing-centre categories do not directly apply; other routes differ.",
            "2.13": "Computational execution and scoring software are available. Required hardware, connectivity and supported platforms are not supplied.",
            "2.14": {
              "preparation": "Not supplied",
              "administration": "Automated execution is described; human administrator time is not supplied.",
              "scoring": "Automated component requires no manual marking; operational human time is not supplied.",
              "analysis": "Software averages problem scores; additional analyst time is not supplied.",
              "feedback": "AI debriefing n/a; stakeholder interpretation time is not supplied."
            },
            "2.15": "Three access-controlled test forms are matched for human difficulty; AI equivalence is not established. ARC-AGI-1 is a separate version. Development tasks serve practice rather than an established alternate-form function.",
            "2.16": "Static published problems and designated test sets; no response-adaptive selection is described.",
            "2.17": "Other: the assessed AI generates answers. Human solvers informed development and form matching, rather than supplying proxy ratings of AI ability."
          },
          "3": {
            "3.1": "Digital scoring from AI outputs.",
            "3.2": "At most two attempts per new input; an exact match earns 1, otherwise 0. Input scores are averaged within each problem, then problem scores are averaged. No guessing correction is described.",
            "3.3": "Raw proportion solved; no percentile or standard-score scale supplied.",
            "3.4": "n/a; no standard-score transformation described.",
            "3.5": "No differentiated norms supplied; human difficulty matching is not a norm conversion."
          },
          "4": {
            "4.1": "Digitally generated numerical results are described. Psychologically interpretive reports are not established; report inventory is not supplied.",
            "4.2": "Verified-testing results reportedly include outputs, costs, times and problem scores.",
            "4.3": "Format, graphics and interactivity not supplied.",
            "4.4": "Other: numerical performance reporting; construct-, factor- or pattern-based narrative structure not established.",
            "4.5": "Context sensitivity not supplied.",
            "4.6": "Numerical aggregation is specified; report-development procedures are not supplied.",
            "4.7": "Modifiability not supplied.",
            "4.8": "Score calculation is explicit; links from scores to broader reasoning interpretations are not established.",
            "4.9": "Task-performance results and operational information; additional interpretive content not supplied.",
            "4.10": "Researchers can inspect public results; formal recipient categories and qualifications are not supplied."
          },
          "5": {
            "5.1": "Technical report, public problems, software, marking tests, verified-testing policies and dated change record are described; complete user and technical manuals are not supplied.",
            "5.2": "Public digital materials and releases; specific publication formats are not fully supplied.",
            "5.3": "User qualifications are unclear. Controlled hidden-data access and selected-submission code review are described, but professional qualification requirements are not."
          },
          "general_description": "ARC-AGI-2 evaluates AI performance on coloured-grid transformation problems. Each problem supplies worked input-output examples, followed by new inputs requiring generated output grids. Developers describe the intended capability as inferring unfamiliar rules with little specialist knowledge and connect it to broader reasoning. The release contains 1,000 development problems and three 120-problem test sets with different access arrangements. Human puzzle-solving results informed selection and matching of test-set difficulty. Official software permits two attempts per new input, awards credit only for exact grid matches and averages input success within problems before averaging problem scores. No distinct skill scales or normative score conversions are supplied. ARC Prize verified evaluations specify settings and spending limits and use one run; other evaluation routes may differ."
        },
        "part_B": {
          "information_sources": "Only the supplied ARC-AGI-2 passage, including its descriptions of inspected sources. No original software, archive, report or confidential material was independently examined.",
